var ok0=['لا توجد أخطاء',function(c){return !c.err&&!c.logs.some(function(l){return l[0]==='!'})}];
var O=function(c){return out(c)};
var cs=function(d,el,p){return d.defaultView.getComputedStyle(el,p||null)};

var lessons=[
/* ───────── HTML: الوسائط ───────── */
{id:'hM',k:'html',ic:'play',t:'الصوت والفيديو والإطارات',
g:'تضيف الفيديو والصوت وتضمّن محتوى من مواقع أخرى داخل صفحتك.',
s:['`<video controls>` و`<audio controls>` يعرضان مشغّلاً جاهزاً.','`<source>` يعطي المتصفح أكثر من صيغة ليختار المناسبة.','`<iframe>` يضمّن صفحة أخرى، وله دائماً `title` يصف محتواه.'],
e:'نسيان `controls`، فيظهر الفيديو بلا أزرار تشغيل ولا يستطيع الزائر تشغيله.',
body:[
'الصفحات الحديثة ليست نصاً وصوراً فقط. HTML تعرض الفيديو والصوت **بلا أي برنامج إضافي**، بوسمين بسيطين:',
{c:'<video src="intro.mp4" controls width="320" poster="cover.jpg"></video>\n\n<audio src="lesson.mp3" controls></audio>'},
'`controls` تُظهر أزرار التشغيل والصوت، و`poster` صورة تظهر قبل التشغيل. وللتوافق مع كل المتصفحات ضع أكثر من صيغة داخل `<source>`، والمتصفح يختار أول صيغة يفهمها:',
{c:'<video controls width="320">\n  <source src="intro.webm" type="video/webm">\n  <source src="intro.mp4" type="video/mp4">\n  متصفحك لا يدعم الفيديو.\n</video>'},
'أما `<iframe>` فيضع **صفحة كاملة داخل صفحتك**: فيديو يوتيوب، أو خريطة، أو نموذج. هكذا تعمل أزرار "تضمين" في المواقع:',
{c:'<iframe src="https://www.youtube.com/embed/VIDEO_ID"\n  title="شرح HTML للمبتدئين"\n  width="320" height="180"\n  loading="lazy" allowfullscreen></iframe>'},
{tip:'`loading="lazy"` يؤجّل تحميل الإطار حتى يقترب منه الزائر، فتفتح صفحتك أسرع. ولا تشغّل الفيديو تلقائياً بالصوت، فهذا يزعج الزوار.'}],
task:'ابنِ مكتبة وسائط: فيديو `<video>` له `controls` ومصدر، وصوت `<audio>` له `controls`، وإطار `<iframe>` له `src` و`title`.',
start:'<h2>مكتبة الوسائط</h2>\n\n',
checks:[['فيديو video له controls',function(d){return d.querySelector('video[controls]')}],['للفيديو مصدر src أو source',function(d){return d.querySelector('video[src], video source[src]')}],['صوت audio له controls',function(d){return d.querySelector('audio[controls]')}],['إطار iframe له src و title',function(d){var f=d.querySelector('iframe[src][title]');return f&&f.title.trim()}]]},

/* ───────── HTML: الوصول ومحركات البحث ───────── */
{id:'hA',k:'html',ic:'eye',t:'صفحة يفهمها الجميع: الوصول وSEO',
g:'تجعل صفحتك سهلة لكل الناس، ومنهم مستخدمو قارئات الشاشة، وتساعد Google على فهمها.',
s:['`<title>` و`<meta name="description">` يظهران في نتائج البحث.','`alt` للصور و`<label>` للحقول ضروريان لقارئ الشاشة.','الزر الذي فيه أيقونة فقط يحتاج `aria-label` يصف وظيفته.'],
e:'صنع زر من `<div>` بدل `<button>`، فلا يعمل بلوحة المفاتيح ولا يعرفه قارئ الشاشة.',
body:[
'المطوّر المحترف لا يسأل فقط "هل تعمل الصفحة؟" بل "هل تعمل **للجميع**؟". هناك من يتصفح بقارئ شاشة ينطق المحتوى، ومن يستعمل لوحة المفاتيح فقط. وهذا يسمى **إمكانية الوصول** (Accessibility).',
'والخبر الجميل أن ما يساعد قارئ الشاشة يساعد Google أيضاً. هذان السطران في `<head>` هما ما يظهر في نتيجة البحث:',
{c:'<title>ويب نايل | تعلّم البرمجة بالعربية</title>\n<meta name="description"\n  content="دورة مجانية لتعلّم HTML وCSS وJavaScript خطوة بخطوة.">'},
'استعمل الوسم المناسب لكل وظيفة: `<button>` للأفعال، و`<a>` للتنقل. وإذا كان الزر أيقونة بلا نص، صِف وظيفته بـ `aria-label`:',
{c:'<button aria-label="إغلاق">✕</button>\n<button aria-label="بحث">🔍</button>\n\n<nav aria-label="القائمة الرئيسية">...</nav>'},
'وقاعدة ذهبية: رتّب العناوين بلا قفز (`h1` ثم `h2` ثم `h3`)، واجعل لون النص واضحاً على خلفيته.',
{tip:'جرّب صفحتك بلوحة المفاتيح فقط: اضغط Tab لتتنقل. إن لم تستطع الوصول لكل زر ورابط، فهناك مشكلة.'}],
task:'أصلح الصفحة: اكتب `<title>` ووصفاً في `<meta name="description">` (10 أحرف على الأقل)، وأعطِ زر الإغلاق `aria-label`، واكتب `alt` للصورة.',
start:'<title></title>\n<meta name="description" content="">\n\n<button>✕</button>\n<h1>رحلة إلى النيل</h1>\n<img src="https://picsum.photos/200/120" alt="">\n',
checks:[['title فيه نص',function(d){return [].some.call(d.querySelectorAll('title'),function(t){return t.textContent.trim()})}],['وصف meta بـ 10 أحرف أو أكثر',function(d){var m=d.querySelector('meta[name=description]');return m&&(m.getAttribute('content')||'').trim().length>=10}],['زر له aria-label',function(d){var b=d.querySelector('button[aria-label]');return b&&b.getAttribute('aria-label').trim()}],['صورة لها alt غير فارغ',function(d){var i=d.querySelector('img');return i&&i.alt.trim()}]]},

/* ───────── CSS: الصور المرنة والدوال الحديثة ───────── */
{id:'cR',k:'css',ic:'phone',t:'صور مرنة ومقاسات ذكية',
g:'تجعل الصور والنصوص تتكيف مع أي شاشة دون كتابة @media كثيرة.',
s:['`max-width: 100%` يمنع الصورة من الخروج عن الشاشة.','`aspect-ratio` يحدد نسبة العرض للارتفاع، و`object-fit: cover` يملأ المساحة دون تشويه.','`clamp(أصغر, مفضّل, أكبر)` حجم مرن له حدّ أدنى وأعلى.'],
e:'تحديد `width` و`height` معاً بالبكسل للصورة، فتتمدد أو تنضغط وتتشوه.',
body:[
'أكثر مشكلة تكسر صفحات الهاتف: صورة عرضها 1200px على شاشة عرضها 380px. الحل سطر واحد:',
{c:'img {\n  max-width: 100%;\n  height: auto;\n}'},
'وحين تريد مساحة بنسبة ثابتة (مثل 16:9) والصورة تملؤها دون أن تتشوه، استعمل `aspect-ratio` مع `object-fit`:',
{c:'.cover {\n  width: 100%;\n  aspect-ratio: 16 / 9;\n  object-fit: cover;   /* يقصّ الزائد بدل التشويه */\n  border-radius: 16px;\n}'},
'الدوال الحديثة `min()` و`max()` و`clamp()` تجعل المقاس يتغير مع الشاشة وحده. `clamp` تأخذ: أصغر قيمة، والقيمة المفضلة، وأكبر قيمة:',
{c:'h1 {\n  font-size: clamp(24px, 6vw, 48px);\n}\n.box {\n  width: min(90%, 700px);\n}'},
{tip:'`width: min(90%, 700px)` تعني: خذ 90% من الشاشة، لكن لا تتجاوز 700px. سطر واحد بدل `width` و`max-width` معاً.'}],
task:'اجعل الصورة `.cover` بعرض `100%` مع `aspect-ratio` و`object-fit: cover`، واجعل حجم خط `h1` مرناً بـ `clamp()`.',
start:'<style>\n  .cover {\n    \n  }\n  h1 {\n    \n  }\n</style>\n<h1>رحلة إلى النيل</h1>\n<img class="cover" src="https://picsum.photos/800/500" alt="منظر النيل">',
checks:[['.cover عرضها 100%',function(d){return anyRule(d,function(r){return r.selectorText&&r.selectorText.indexOf('.cover')>-1&&(r.style.width==='100%'||r.style.maxWidth==='100%')})}],['.cover لها aspect-ratio',function(d){return anyRule(d,function(r){return r.selectorText&&r.selectorText.indexOf('.cover')>-1&&r.style.aspectRatio&&r.style.aspectRatio!=='auto'})}],['object-fit: cover',function(d){var i=d.querySelector('img.cover');return i&&cs(d,i).objectFit==='cover'}],['حجم h1 بـ clamp()',function(d){return anyRule(d,function(r){return r.style&&/clamp\(/.test(r.style.fontSize)})}]]},

/* ───────── CSS: الحالات والعناصر الزائفة ───────── */
{id:'cPs',k:'css',ic:'sparkles',t:'الحالات والعناصر الزائفة',
g:'تنسّق العناصر حسب ترتيبها وحالتها، وتضيف زخارف دون لمس HTML.',
s:['`:nth-child(even)` يختار العناصر الزوجية، و`:first-child` الأول.','`:focus` عند تحديد الحقل، وهو مهم لمستخدمي لوحة المفاتيح.','`::before` و`::after` يضيفان محتوى بـ `content`.'],
e:'نسيان `content: ""` مع `::before`، فلا يظهر العنصر الزائف إطلاقاً.',
body:[
'رأيت `:hover` من قبل. هذه **حالة زائفة** (pseudo-class): تختار العنصر حسب حالته أو مكانه، لا حسب اسمه. أشهرها:',
{c:'li:first-child   { font-weight: bold; }   /* الأول */\nli:last-child    { color: gray; }         /* الأخير */\ntr:nth-child(even) { background: #eef; }  /* الزوجي */\ninput:focus      { outline: 2px solid teal; } /* عند الكتابة */'},
'`:nth-child(even)` تلوّن الصفوف بالتناوب، وهي حيلة ترى أثرها في كل جدول محترف. وتقبل أيضاً `odd` أو رقماً مثل `:nth-child(3)`.',
'أما **العنصر الزائف** (بنقطتين `::`) فيصنع عنصراً غير موجود في HTML. `::before` قبل المحتوى و`::after` بعده، ولا يظهران إلا مع `content`:',
{c:'li::before {\n  content: "✔ ";\n  color: teal;\n}\n.price::after {\n  content: " جنيه";\n}\ninput::placeholder { color: #999; }'},
{tip:'لا تحذف إطار `:focus` لأن شكله لا يعجبك. استبدله بشكل أجمل، فمستخدم لوحة المفاتيح يحتاجه ليعرف أين هو.'}],
task:'لوّن عناصر القائمة الزوجية بـ `li:nth-child(even)`، وأضف `::before` لكل `li` فيه `content`، وأعطِ الحقل تنسيقاً عند `:focus`.',
start:'<style>\n  li {\n    padding: 8px;\n    list-style: none;\n  }\n  \n</style>\n<ul>\n  <li>HTML</li>\n  <li>CSS</li>\n  <li>JavaScript</li>\n  <li>Git</li>\n</ul>\n<input placeholder="ابحث...">',
checks:[['الصفوف الزوجية بخلفية مختلفة',function(d){var l=d.querySelectorAll('li');return l.length>=2&&cs(d,l[1]).backgroundColor!==cs(d,l[0]).backgroundColor}],['li::before فيه content',function(d){var l=d.querySelector('li');if(!l)return false;var c=cs(d,l,'::before').content;return c&&c!=='none'&&c!=='normal'}],['قاعدة :focus',function(d){return anyRule(d,function(r){return /:focus/.test(r.selectorText||'')&&r.style.length>0})}]]},

/* ───────── JS: المعامل الثلاثي و switch ───────── */
{id:'jT',k:'js',ic:'split',t:'المعامل الثلاثي و switch',
g:'تكتب القرارات القصيرة في سطر واحد، والاختيارات الكثيرة بشكل مرتب.',
s:['`شرط ? قيمة1 : قيمة2` يعيد قيمة حسب الشرط.','`switch` يقارن قيمة واحدة بعدة احتمالات `case`.','`break` ينهي كل `case`، و`default` لما لا يطابق أي احتمال.'],
e:'نسيان `break` في `switch`، فيُكمل التنفيذ إلى الحالة التالية.',
body:[
'كثيراً ما تحتاج قيمة واحدة من اثنتين حسب شرط. بدل `if/else` من خمسة أسطر، استعمل **المعامل الثلاثي**:',
{c:'const age = 20;\nconst type = age >= 18 ? "بالغ" : "قاصر";\nconsole.log(type); // بالغ'},
'اقرأه هكذا: "هل العمر 18 أو أكثر؟ إن نعم فـ بالغ، وإلا فـ قاصر". استعمله للقرارات القصيرة فقط، وللمعقّدة ابقَ على `if`.',
'وحين تقارن **قيمة واحدة** بخيارات كثيرة، يكون `switch` أوضح من سلسلة `else if`:',
{c:'const lang = "css";\nswitch (lang) {\n  case "html":\n    console.log("الهيكل");\n    break;\n  case "css":\n    console.log("الشكل");\n    break;\n  default:\n    console.log("لغة أخرى");\n}'},
{tip:'يمكن جمع أكثر من حالة لنفس النتيجة بكتابتها متتالية: `case "السبت": case "الجمعة": console.log("عطلة"); break;`'}],
task:'استعمل `switch` على `light`: "أحمر" تطبع "قف"، و"أصفر" تطبع "استعد"، و"أخضر" تطبع "انطلق"، وغير ذلك "إشارة غير معروفة". ثم اطبع حالة `age` بالمعامل الثلاثي: "بالغ" أو "قاصر".',
start:'const light = "أصفر";\nconst age = 15;\n\n',
checks:[ok0,['استعملت switch و case و break',function(c){return /\bswitch\s*\(/.test(c.code)&&/\bcase\b/.test(c.code)&&/\bbreak\b/.test(c.code)}],['استعملت default',function(c){return /\bdefault\s*:/.test(c.code)}],['استعملت المعامل الثلاثي ? :',function(c){return /[^?.]\?\s*["'`\w][^:;\n]*:/.test(c.code.replace(/\bcase\b[^:]*:/g,''))}],['النتيجتان صحيحتان',function(c){var m=c.code.match(/light\s*=\s*["'`]([^"'`]*)["'`]/),a=c.code.match(/age\s*=\s*(\d+)/);if(!m||!a)return false;var e={'أحمر':'قف','أصفر':'استعد','أخضر':'انطلق'}[m[1]]||'إشارة غير معروفة',o=O(c);return o.indexOf(e)>-1&&o.indexOf(+a[1]>=18?'بالغ':'قاصر')>-1}]]},

/* ───────── JS: التفكير كمبرمج ───────── */
{id:'jP',k:'js',ic:'braces',t:'فكّر كمبرمج: حل المشكلات',
g:'تتعلم الطريقة التي يحل بها المبرمجون أي مشكلة: الفهم، ثم التقسيم، ثم الكود، ثم الاختبار.',
s:['افهم المطلوب بأمثلة قبل أن تكتب أي كود.','قسّم المشكلة الكبيرة إلى خطوات صغيرة، واكتبها بالعربية أولاً (كود زائف).','حوّل كل خطوة إلى سطر كود، واختبر بعد كل خطوة.'],
e:'البدء بكتابة الكود مباشرة دون فهم المطلوب، ثم التوه في الأخطاء.',
body:[
'البرمجة ليست حفظ أوامر، بل **مهارة حل المشكلات**. هذه الخطوات الأربع يستعملها كل مبرمج محترف، مهما كبرت المشكلة:',
'**1. افهم:** أعد صياغة المطلوب بكلماتك، وجرّب أمثلة صغيرة بيدك. **2. قسّم:** جزّئ المشكلة إلى خطوات. **3. اكتب كوداً زائفاً:** صِف الحل بالعربية قبل الكود. **4. حوّل واختبر:** خطوة خطوة.',
'مثال: "اطبع الأرقام الزوجية من 1 إلى 10". الكود الزائف:',
{c:'// لكل رقم من 1 إلى 10:\n//   إذا كان باقي قسمته على 2 يساوي 0:\n//     اطبعه'},
'ثم يصبح كل سطر عربي سطراً برمجياً تعرفه مسبقاً:',
{c:'for (let n = 1; n <= 10; n++) {\n  if (n % 2 === 0) {\n    console.log(n);\n  }\n}'},
'لاحظ أن ترتيب الشروط مهم: إذا كان لشرطين نفس النتيجة الجزئية، **افحص الأكثر تحديداً أولاً**.',
{tip:'إن علقت، اشرح المشكلة بصوت عالٍ لشخص أو حتى لدمية. يسميها المبرمجون "طريقة البطة المطاطية"، وهي تعمل فعلاً.'}],
task:'اطبع الأرقام من 1 إلى 15 كلٌّ في سطر، لكن: مضاعفات 3 تطبع "ويب" بدل الرقم، ومضاعفات 5 تطبع "نايل"، ومضاعفات الاثنين معاً تطبع "ويب نايل". (فكّر: أي شرط تفحصه أولاً؟)',
start:'// الخطوة 1: حلقة من 1 إلى 15\n// الخطوة 2: افحص مضاعفات 3 و 5 معاً أولاً\n// الخطوة 3: ثم مضاعفات 3، ثم مضاعفات 5، وإلا اطبع الرقم\n\n',
checks:[ok0,['استعملت حلقة',function(c){return /\b(for|while)\s*\(/.test(c.code)}],['طُبع 15 سطراً',function(c){return O(c).length===15}],['الناتج كله صحيح',function(c){var o=O(c);for(var i=1;i<=15;i++){var e=i%15===0?'ويب نايل':i%3===0?'ويب':i%5===0?'نايل':String(i);if((o[i-1]||'').trim()!==e)return false}return true}]]},

/* ───────── JS: دوال المصفوفات المتقدمة ───────── */
{id:'jM',k:'js',ic:'layers',t:'دوال المصفوفات المتقدمة',
g:'تبحث في البيانات وتجمعها وترتّبها بسطر واحد، كما يفعل المحترفون.',
s:['`find` تعيد أول عنصر مطابق، و`some`/`every` تجيب بنعم أو لا.','`reduce` تجمع المصفوفة في قيمة واحدة كالمجموع.','`sort((a, b) => a - b)` ترتّب الأرقام تصاعدياً.'],
e:'استعمال `sort()` بلا دالة مقارنة مع الأرقام: `[10, 9, 1].sort()` تعطي `[1, 10, 9]`.',
body:[
'تعرّفت على `map` و`filter`. هذه دوال أخرى تختصر حلقات كاملة:',
{c:'const nums = [4, 9, 15, 2];\nconsole.log(nums.find(n => n > 5));    // 9  أول عنصر مطابق\nconsole.log(nums.some(n => n > 10));   // true  هل يوجد واحد؟\nconsole.log(nums.every(n => n > 0));   // true  هل كلها؟\nconsole.log(nums.includes(2));         // true'},
'`reduce` أقواها: تمر على العناصر وتحمل معها **مجمِّعاً** يتراكم. القيمة بعد الفاصلة هي بدايته:',
{c:'const total = nums.reduce((sum, n) => sum + n, 0);\nconsole.log(total); // 30'},
'وللترتيب استعمل `sort` مع دالة مقارنة. `a - b` تصاعدي و`b - a` تنازلي، وتعمل مع الكائنات أيضاً:',
{c:'const items = [{ t: "قلم", p: 5 }, { t: "كتاب", p: 30 }, { t: "ممحاة", p: 2 }];\nconst sorted = [...items].sort((a, b) => a.p - b.p);\nconsole.log(sorted.map(x => x.t).join("، ")); // ممحاة، قلم، كتاب'},
{tip:'`sort` تغيّر المصفوفة الأصلية. لذلك ننسخها أولاً بـ `[...items]` إن أردنا الإبقاء على الترتيب الأصلي.'}],
task:'من مصفوفة `products` اطبع: المجموع الكلي للأسعار بـ `reduce`، ثم اسم أول منتج سعره أكبر من 40 بـ `find`، ثم هل كل الأسعار أكبر من صفر بـ `every`، ثم الأسماء مرتبة من الأرخص للأغلى مفصولة بـ "، ".',
start:'const products = [\n  { title: "قلم", price: 5 },\n  { title: "حقيبة", price: 80 },\n  { title: "دفتر", price: 12 },\n  { title: "آلة حاسبة", price: 45 }\n];\n\n',
checks:[ok0,['المجموع 142 بـ reduce',function(c){return /\.reduce\(/.test(c.code)&&O(c).some(function(x){return /(^|\D)142(\D|$)/.test(x)})}],['أول منتج أغلى من 40: حقيبة بـ find',function(c){return /\.find\(/.test(c.code)&&O(c).some(function(x){return x.trim()==='حقيبة'||/^\{.*حقيبة/.test(x)})}],['every تعطي true',function(c){return /\.every\(/.test(c.code)&&O(c).some(function(x){return /\btrue\b/.test(x)})}],['الترتيب: قلم، دفتر، آلة حاسبة، حقيبة',function(c){return /\.sort\(/.test(c.code)&&O(c).some(function(x){var a=x.indexOf('قلم'),b=x.indexOf('دفتر'),k=x.indexOf('آلة حاسبة'),h=x.indexOf('حقيبة');return a>-1&&a<b&&b<k&&k<h})}]]},

/* ───────── JS: الصيغ الحديثة ───────── */
{id:'jE',k:'js',ic:'sparkles',t:'JavaScript الحديثة',
g:'تقرأ وتكتب الصيغ الحديثة التي ستراها في كل مشروع ومكتبة حقيقية.',
s:['التفكيك: `const { name } = user` و`const [a, b] = arr`.','النشر `...` ينسخ المصفوفات والكائنات ويدمجها.','القيمة الافتراضية: `function f(x = 1)`، و`?.` يمنع الخطأ إن كانت القيمة غير موجودة.'],
e:'نسخ كائن بـ `const b = a` ثم تعديله، فيتغير الأصل أيضاً. استعمل `{ ...a }` لنسخة حقيقية.',
body:[
'منذ 2015 أضيفت إلى JavaScript صيغ تختصر الكود كثيراً. ستراها في كل مكان، فلنتعلمها.',
'**التفكيك** يستخرج القيم من كائن أو مصفوفة إلى متغيرات مباشرة:',
{c:'const user = { name: "سارة", city: "الخرطوم" };\nconst { name, city } = user;\nconsole.log(name, city); // سارة الخرطوم\n\nconst [first, second] = ["HTML", "CSS"];\nconsole.log(first); // HTML'},
'**النشر** `...` يفرد العناصر. به تنسخ وتدمج دون تغيير الأصل:',
{c:'const a = [1, 2];\nconst b = [...a, 3];              // [1, 2, 3]\nconst updated = { ...user, age: 22 }; // نسخة فيها age\nconsole.log(updated.age); // 22'},
'**القيمة الافتراضية** تُستعمل إن لم يُرسل المعامل، و**السلسلة الاختيارية** `?.` تعيد `undefined` بدل أن ينهار البرنامج، و`??` تعطي بديلاً:',
{c:'function greet(name = "زائر") {\n  return "أهلاً " + name;\n}\nconsole.log(greet());        // أهلاً زائر\n\nconsole.log(user.address?.street);     // undefined بلا خطأ\nconsole.log(user.phone ?? "لا يوجد"); // لا يوجد'},
{tip:'`?.` مفيدة جداً مع البيانات القادمة من الإنترنت، لأنك لا تضمن وجود كل حقل فيها.'}],
task:'من الكائن `user`: 1) استخرج `name` و`city` بالتفكيك واطبعهما. 2) أنشئ `updated` بالنشر `...user` مع `age: 22` واطبع `updated.age`. 3) اكتب دالة `greet(name = "زائر")` تعيد "أهلاً " + name، واطبع `greet()` و`greet("سارة")`.',
start:'const user = { name: "سارة", city: "الخرطوم" };\n\n',
checks:[ok0,['تفكيك من user',function(c){return /(const|let|var)\s*\{[^}]*\bname\b[^}]*\}\s*=\s*user\b/.test(c.code)}],['طُبع الاسم والمدينة',function(c){var o=O(c).join('\n');return o.indexOf('سارة')>-1&&o.indexOf('الخرطوم')>-1}],['نشر ...user وطُبع 22',function(c){return /\.\.\.user\b/.test(c.code)&&O(c).indexOf('22')>-1}],['قيمة افتراضية: أهلاً زائر',function(c){return /\(\s*name\s*=\s*["'`]/.test(c.code)&&O(c).indexOf('أهلاً زائر')>-1}],['طُبع أهلاً سارة',function(c){return O(c).indexOf('أهلاً سارة')>-1}]]},

/* ───────── JS: المؤقتات ───────── */
{id:'jTm',k:'js',ic:'repeat',t:'المؤقتات: التأخير والتكرار',
page:'<p id="count" style="font-size:40px;font-weight:900;margin:0">3</p>\n<p id="msg"></p>',
g:'تنفّذ الكود بعد مدة أو كل مدة، لتصنع عدّادات وساعات ورسائل تختفي.',
s:['`setTimeout(دالة, مدة)` تنفّذ مرة واحدة بعد المدة.','`setInterval(دالة, مدة)` تنفّذ كل مدة حتى توقفها.','`clearInterval(id)` يوقف التكرار، والمدة بالملّي ثانية (1000 = ثانية).'],
e:'نسيان `clearInterval`، فيستمر المؤقت إلى الأبد حتى بعد انتهاء الحاجة إليه.',
body:[
'أحياناً تريد أن يحدث شيء **لاحقاً** لا الآن: رسالة تختفي بعد ثانيتين، أو عدّاد ينقص كل ثانية. المدة دائماً بالملّي ثانية:',
{c:'setTimeout(() => {\n  console.log("مرّت ثانيتان");\n}, 2000);'},
'`setInterval` تكرر التنفيذ، وتعيد **رقماً** نحفظه لنوقف المؤقت به لاحقاً:',
{c:'let n = 5;\nconst id = setInterval(() => {\n  n--;\n  console.log(n);\n  if (n === 0) {\n    clearInterval(id);\n    console.log("انتهى!");\n  }\n}, 1000);'},
'لاحظ أن الكود بعد `setTimeout` لا ينتظرها، بل يُكمل فوراً. الدالة تُنفَّذ لاحقاً حين يحين وقتها، وهذا أول لقاء لك مع **البرمجة غير المتزامنة**.',
{tip:'في التمرين نستعمل مدة قصيرة (50 ملّي ثانية) ليظهر الناتج بسرعة في المحرر. في تطبيقك الحقيقي استعمل 1000 لعدّاد بالثواني.'}],
task:'اصنع عدّاداً تنازلياً: كل 50 ملّي ثانية أنقص `count` بواحد واعرضه في `#count`. عند الوصول إلى 0 أوقف المؤقت بـ `clearInterval` واكتب "انطلق!" في `#msg`.',
start:'let count = 3;\nconst countEl = document.querySelector("#count");\nconst msg = document.querySelector("#msg");\n\n',
checks:[ok0,['استعملت setInterval و clearInterval',function(c){return /setInterval\(/.test(c.code)&&/clearInterval\(/.test(c.code)}],['العدّاد وصل إلى 0',function(c){var e=c.doc.querySelector('#count');return e&&e.textContent.trim()==='0'}],['ظهرت "انطلق!" في #msg',function(c){var e=c.doc.querySelector('#msg');return e&&e.textContent.indexOf('انطلق')>-1}]]},

/* ───────── مشروع: تطبيق اختبار ───────── */
{id:'pJ5',k:'js',ic:'trophy',t:'مشروع: تطبيق اختبار سريع',
page:'<h2 id="q"></h2>\n<div id="opts" style="display:grid;gap:8px"></div>\n<p id="score">النتيجة: 0</p>',
g:'تبني تطبيق اختبار كاملاً يجمع البيانات والدوال وDOM والأحداث، مثل التطبيقات الحقيقية.',
s:['البيانات (الأسئلة) منفصلة عن العرض (دالة `show`).','كل ضغطة تحدّث الحالة (`current` و`score`) ثم تعيد الرسم.','هذا النمط "حالة ← رسم" هو أساس React وكل أطر الواجهات الحديثة.'],
e:'إضافة الأزرار دون تفريغ `#opts` أولاً، فتتراكم أزرار الأسئلة السابقة.',
body:[
'هذا مشروع يجمع كل ما تعلمته في JavaScript. الفكرة التي ستحملها معك لكل تطبيق: **افصل البيانات عن طريقة عرضها**.',
'البيانات مصفوفة كائنات، وكل سؤال فيه نصه وخياراته ورقم الإجابة الصحيحة. ومعها متغيران للحالة: رقم السؤال الحالي، والنتيجة.',
'دالة `show()` ترسم السؤال الحالي: تكتب النص في `#q`، وتفرّغ `#opts`، ثم تنشئ زراً لكل خيار:',
{c:'function show() {\n  const item = questions[current];\n  qEl.textContent = item.text;\n  opts.innerHTML = "";\n  item.options.forEach((opt, i) => {\n    const b = document.createElement("button");\n    b.textContent = opt;\n    b.addEventListener("click", () => choose(i));\n    opts.appendChild(b);\n  });\n}'},
'ودالة `choose(i)` تفحص الإجابة وتزيد النتيجة إن كانت صحيحة، ثم تنتقل للسؤال التالي، أو تعرض النهاية إذا انتهت الأسئلة.',
{tip:'ابدأ بـ `show()` وحدها وتأكد أن السؤال الأول يظهر، ثم أضف `choose`. البناء خطوة خطوة أسرع من كتابة كل شيء دفعة واحدة.'}],
task:'أكمل التطبيق: `show()` تعرض السؤال الحالي في `#q` وزراً لكل خيار في `#opts`. عند الضغط: إن كانت الإجابة صحيحة زِد `score` واكتب "النتيجة: " + score في `#score`، ثم انتقل للسؤال التالي. بعد آخر سؤال اكتب "انتهى الاختبار" في `#q` وفرّغ `#opts`.',
start:'const questions = [\n  { text: "ما لغة شكل الصفحة؟", options: ["HTML", "CSS", "JavaScript"], answer: 1 },\n  { text: "ما لغة البرمجة في المتصفح؟", options: ["HTML", "CSS", "JavaScript"], answer: 2 }\n];\nlet current = 0;\nlet score = 0;\nconst qEl = document.querySelector("#q");\nconst opts = document.querySelector("#opts");\nconst scoreEl = document.querySelector("#score");\n\nfunction show() {\n  \n}\n\nfunction choose(i) {\n  \n}\n\nshow();\n',
tests:'setTimeout(function(){var Q=document.getElementById("q"),B=function(){return document.querySelectorAll("#opts button")},S=document.getElementById("score");__t(Q.textContent);__t(B().length);if(B()[1])B()[1].click();__t(Q.textContent);__t(S.textContent);if(B()[0])B()[0].click();__t(Q.textContent);__t(S.textContent);__t(B().length)},60);',
checks:[ok0,['السؤال الأول ظاهر في #q',function(c){return String(c.t[0]||'').indexOf('شكل')>-1}],['3 أزرار للخيارات',function(c){return c.t[1]===3}],['بعد الإجابة ظهر السؤال الثاني',function(c){return String(c.t[2]||'').indexOf('البرمجة')>-1}],['الإجابة الصحيحة زادت النتيجة إلى 1',function(c){return /1/.test(String(c.t[3]||''))}],['بعد آخر سؤال: "انتهى الاختبار"',function(c){return String(c.t[4]||'').indexOf('انتهى')>-1&&c.t[6]===0}],['الإجابة الخاطئة لم تزد النتيجة',function(c){var s=String(c.t[5]||'');return /1/.test(s)&&!/2/.test(s)}]]},

/* ───────── Git و GitHub ───────── */
{id:'git',k:'html',ic:'terminal',t:'Git وGitHub: احفظ تاريخ مشروعك',
g:'تفهم كيف يحفظ المطورون نسخ مشاريعهم ويتعاونون عليها، وتكتب دليل أوامرك الخاص.',
s:['Git يحفظ "لقطات" من مشروعك تعود إليها متى شئت.','الدورة اليومية: `git add` ثم `git commit -m "..."` ثم `git push`.','GitHub موقع يستضيف مشاريع Git، وهو سيرتك الذاتية كمبرمج.'],
e:'كتابة رسائل commit غامضة مثل "تعديل"، فلا تعرف لاحقاً ما الذي تغيّر.',
body:[
'تخيّل أنك عدّلت موقعك وخرّبته، وتتمنى العودة لنسخة الأمس. **Git** هو البرنامج الذي يحقق ذلك: يحفظ كل نسخة من مشروعك مع وصف لما تغيّر، ويستعمله كل مطور في العالم.',
'تبدأ مرة واحدة بـ `git init` داخل مجلد المشروع. ثم دورتك اليومية ثلاث خطوات:',
{c:'git add .                          # جهّز الملفات المعدّلة\ngit commit -m "إضافة نموذج التواصل"  # احفظ لقطة مع وصف\ngit push                           # ارفعها إلى GitHub'},
'**GitHub** موقع يحفظ مشاريعك على الإنترنت. هو نسخة احتياطية، ومكان للتعاون مع غيرك، و**معرض أعمالك** الذي يطلبه أصحاب العمل. ومنه تنشر موقعك مجاناً بـ GitHub Pages كما سترى في الدرس التالي.',
'أوامر أخرى مهمة: `git status` يعرض ما تغيّر، و`git log` يعرض التاريخ، و`git clone رابط` ينزّل مشروعاً موجوداً.',
{tip:'اكتب رسالة commit تصف **ماذا** تغيّر: "إصلاح زر الإرسال في الهاتف" أفضل بكثير من "تعديلات". ونفّذ commit صغيراً بعد كل خطوة مكتملة.'}],
task:'اكتب دليل أوامر Git الخاص بك: جدول `<table>` فيه صف عناوين `<th>`، و4 صفوف على الأقل لأوامر `git init` و`git add` و`git commit` و`git push`، واكتب كل أمر داخل `<code>` وبجانبه شرحه.',
start:'<h1>دليل أوامر Git</h1>\n<table>\n  <tr>\n    <th>الأمر</th>\n    <th>وظيفته</th>\n  </tr>\n  <tr>\n    <td><code>git init</code></td>\n    <td>ينشئ مستودعاً جديداً في المجلد</td>\n  </tr>\n</table>\n',
checks:[['جدول فيه عناوين th',function(d){return d.querySelectorAll('table th').length>=2}],['5 صفوف على الأقل (عناوين + 4 أوامر)',function(d){return d.querySelectorAll('table tr').length>=5}],['الأوامر الأربعة داخل code',function(d){var t=[].map.call(d.querySelectorAll('table code'),function(x){return x.textContent}).join(' ');return ['git init','git add','git commit','git push'].every(function(k){return t.indexOf(k)>-1})}],['لكل أمر شرح',function(d){var r=[].slice.call(d.querySelectorAll('table tr')).filter(function(tr){return tr.querySelector('code')});return r.length>=4&&r.every(function(tr){var td=tr.querySelectorAll('td');return td.length>=2&&td[td.length-1].textContent.trim().length>3})}]]}
];

